def page(lang,path,title,desc,body,extra_ld=None):
  t=T[lang]; p=PFX[lang]
  alt_en=D+'/'+path; alt_es=D+'/es/'+path; alt_zh=D+'/zh/'+path; me=D+p+'/'+path
